// Responsive chart helper
function makeChart(containerId, build){
  const el = $(containerId);
  const render = () => {
    const w = Math.max(300, Math.round(el.clientWidth));
    el.innerHTML = build(w);
  };
  render();
  const ro = new ResizeObserver(render);
  ro.observe(el);
}
```

