  const slot = plotW/yearList.length;
  const step = 20;
  const tickMax = Math.max(step, Math.ceil(maxStack/step)*step);
  const yFor = val => padT + plotH - (val/tickMax)*plotH;
  const h = padT + plotH + padB;
  const labelEvery = slot < 32 ? 2 : 1;
  let svg = `<svg width="${w}" height="${h}" style="width:${w}px;height:auto" role="img" aria-label="Stacked bar chart of papers per year by collection method">`;
