  vals.forEach((v,i)=>{
    const x = xFor(v);
    const y = padT + i*16;
    svg += `<circle cx="${x}" cy="${y+5}" r="3.5" fill="#1f6feb"><title>${v}</title></circle>`;
    if(narrow && v < 1000) return;
    const text = fmtNum(v);
